            to right,
            transparent 0px,
            transparent 98px,
            var(--accent-1) 98px,
            var(--accent-1) 100px
        ),
        /* Step separator lines (every CELL_WIDTH=25px) */
        repeating-linear-gradient(
            to right,
            transparent 0px,
            transparent 24px,
            var(--bg-tertiary) 24px,
            var(--bg-tertiary) 25px
        ),
        /* Row separator lines (every ROW_HEIGHT=32px) */
        repeating-linear-gradient(
            to bottom,
            transparent 0px,
            transparent 31px,
            var(--bg-tertiary) 31px,
            var(--bg-tertiary) 32px
        );
}

/* Piano scroll custom scrollbar */
.piano-scroll::-webkit-scrollbar {
    height: 8px;
}

.piano-scroll::-webkit-scrollbar-track {
    background: var(--bg-secondary);
}

.piano-scroll::-webkit-scrollbar-thumb {
    background: var(--accent-3);
    border-radius: 4px;
}

.piano-scroll::-webkit-scrollbar-corner {
    background-color: transparent;
    display: none;
}
```

## 注意事项

1. **不要修改** `public/styles/theme.css`（该文件已标记为弃用）
2. 只修改 `src/styles/index.css`
3. 这些样式只影响乐谱编辑器组件，不会影响其他使用 `theme-*` 前缀的组件
4. 保留 `index.css` 中已有的 `.piano-grid` 和 `.piano-playhead` 样式，但需要扩展 `.piano-grid` 样式以包含完整的网格线背景图案

